import{_ as a,C as n,c as l,o as f,ag as o,j as t,G as r,a as s}from"./chunks/framework.Bw-5EFTY.js";const y=JSON.parse('{"title":"MemberPress Integration with FluentAffiliate","description":"","frontmatter":{},"headers":[],"relativePath":"guide/integrations/memberpress-integration-with-fluentaffiliate.md","filePath":"guide/integrations/memberpress-integration-with-fluentaffiliate.md","lastUpdated":1755603750000}'),u={name:"guide/integrations/memberpress-integration-with-fluentaffiliate.md"};function m(g,e,p,c,h,b){const i=n("ZoomableImage");return f(),l("div",null,[e[0]||(e[0]=o('<h1 id="memberpress-integration-with-fluentaffiliate" tabindex="-1">MemberPress Integration with FluentAffiliate <a class="header-anchor" href="#memberpress-integration-with-fluentaffiliate" aria-label="Permalink to &quot;MemberPress Integration with FluentAffiliate&quot;">​</a></h1><p>MemberPress is one of the most popular and powerful membership plugins for WordPress, making it easy to sell access to your content, courses, and digital products. By connecting MemberPress with FluentAffiliate, you can launch a robust affiliate program and empower your members to promote your site while earning commissions.</p><p>This guide will walk you through the simple steps to integrate MemberPress with FluentAffiliate.</p><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>MemberPress is a pro feature of FluentAffiliate. To use it, you need FluentAffiliate Pro.</p><p>To get started, you must first install and activate the MemberPress plugin on your WordPress website.</p></div><h2 id="enable-memberpress-in-fluentaffiliate" tabindex="-1">Enable MemberPress in FluentAffiliate <a class="header-anchor" href="#enable-memberpress-in-fluentaffiliate" aria-label="Permalink to &quot;Enable MemberPress in FluentAffiliate&quot;">​</a></h2><p>First, you need to enable the integration to let the two plugins communicate.</p><ol><li>Once MemberPress is active, go to the <strong>FluentAffiliate Dashboard</strong>.</li><li>From the top menu, click on <strong>Settings</strong>, and from the left sidebar, select the <strong>Integration Settings</strong> option.</li><li>You will see a list of available integrations. Look for <strong>MemberPress</strong> in this list. To enable the integration, click on the <strong>toggle</strong> button next to MemberPress.</li></ol><p>Your <strong>MemberPress</strong> integration with <strong>FluentAffiliate</strong> is now active, allowing affiliates to earn referral commissions on MemberPress course or membership sales.</p><p>Click on the <strong>Manage</strong> button and you&#39;ll find additional settings to customize how affiliate commissions work with your course or membership.</p>',9)),t("p",null,[r(i,{src:"/guide/public/images/integrations/memberpress/integration-setup-options.webp",alt:"Integration Settings"})]),e[1]||(e[1]=o('<h2 id="configure-memberpress-settings" tabindex="-1">Configure MemberPress Settings <a class="header-anchor" href="#configure-memberpress-settings" aria-label="Permalink to &quot;Configure MemberPress Settings&quot;">​</a></h2><p>Click the <strong>Manage</strong> button to open the settings panel. Here, you can set custom commission rates for your memberships that will override your global affiliate settings.</p><p>Here are the options you can configure:</p><ul><li><p><strong>Enable Affiliate Integration for MemberPress:</strong> You must check this box to activate commission tracking for all your MemberPress forms.</p></li><li><p><strong>Enable custom rate for specific membership or categories:</strong> Check this box if you want to offer special commission rates for different membership levels or categories. For example, you could offer a higher commission for your premium membership plan to incentivize affiliates to promote it more.</p></li></ul>',4)),t("p",null,[r(i,{src:"/guide/public/images/integrations/memberpress/memberpress-settings-configuration.webp",alt:"MemberPress Settings"})]),e[2]||(e[2]=o('<h2 id="custom-affiliate-rate-configuration" tabindex="-1">Custom Affiliate Rate Configuration <a class="header-anchor" href="#custom-affiliate-rate-configuration" aria-label="Permalink to &quot;Custom Affiliate Rate Configuration&quot;">​</a></h2><p>After enabling custom rates, you can define your specific commission rules.</p><p>First, choose whether the custom rate will apply <strong>By Specific Products</strong> (which refers to your individual membership levels) or <strong>By Specific Categories</strong>.</p><p>Next, configure the rate:</p><ol><li><p><strong>Select Products:</strong> In the Select field, start typing the name of the membership level you want to set a custom rate for, and choose it from the list that appears.</p></li><li><p><strong>Select Rate:</strong> Enter the commission value (e.g., 30 for 30% or $30). Then, use the dropdown menu to select if the rate is a <strong>Percentage (%)</strong> of the sale or a <strong>Fixed</strong> amount.</p></li><li><p><strong>Add More Rates:</strong> To create another custom rate for a different membership, click the <strong>+Add New Group</strong> button. This will add a new row for you to configure another rule. You can also remove a rule by clicking the red <em>delete</em> icon.</p></li><li><p><strong>Save Settings:</strong> Once you have finished setting up your custom rates, click the <strong>Save Settings</strong> button to apply the changes.</p></li></ol>',5)),t("p",null,[r(i,{src:"/guide/public/images/integrations/memberpress/custom-affiliate-rate-configure.webp",alt:"Custom Affiliate Rate"})]),e[3]||(e[3]=t("h2",{id:"generate-an-affiliate-link",tabindex:"-1"},[s("Generate an Affiliate Link "),t("a",{class:"header-anchor",href:"#generate-an-affiliate-link","aria-label":'Permalink to "Generate an Affiliate Link"'},"​")],-1)),e[4]||(e[4]=t("p",null,[s("Now that the integration is set up, your affiliates can start promoting your Course or Membreships pages. To do this, they need to generate your "),t("a",{href:"/guide/affiliate-portal/generating-affiliate-links"},"affiliate link"),s(" from their affiliate dashboard.")],-1)),e[5]||(e[5]=t("p",null,"If someone purchases the Course using your affiliate link, you'll earn a commission based on the settings you've configured.",-1)),e[6]||(e[6]=t("p",null,"And that's it. This is an easy process to integrate MemberPress with FluentAffiliate.",-1))])}const w=a(u,[["render",m]]);export{y as __pageData,w as default};
